using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Searches for public channel posts using the given query. For optimal performance, the number of returned messages is chosen by TDLib and can be smaller than the specified limit
    /// </summary>
    public Task<TdLib.TdApi.Objects.FoundPublicPosts> SearchPublicPostsAsync(string query = default, string offset = default, int limit = default, long starCount = default)
    {

           using var activity =  StartCallActivity("SearchPublicPostsAsync", typeof(SearchPublicPosts).FullName ?? "SearchPublicPostsAsync");

           try
           {
             return client.SearchPublicPostsAsync(query, offset, limit, starCount);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd